"""
Память компьютера и рабочие места — то, чего нет у обычных ассистентов.

  • «Что я делал вчера?» — время в программах, документы, над которыми работал, сайты.
  • «Где тот сайт про линейные уравнения?», «когда я работал над эссе?» — поиск по окнам и
    истории браузеров (Chrome, Edge, Brave, Opera, Яндекс, Firefox).
  • «Открой эссе, которое я писал во вторник», «открой тот сайт про…» — открывает снова.
  • После запуска в чате: «В прошлый раз: эссе.docx (Word, вчера 22:10). Скажи «продолжим»».
  • «Сохрани это как Учёба» → потом «открой рабочее место Учёба» / «режим учёба» — программы,
    документы и страницы браузера возвращаются как были.
  • Приватность: только на этом компьютере, в облако не уходит; окна инкогнито, менеджеров паролей
    и банков не записываются; хранится 30 дней; «забудь, что я делал сегодня»; WORKLOG=off — выключить.
  • С телефона это тоже работает — облако передаёт вопрос компьютеру.

    python apply_pc_memory.py
    python apply_pc_memory.py --rollback
"""
import base64
import hashlib
import os
import re
import shutil
import subprocess
import sys
import time

for _stream in (sys.stdout, sys.stderr):
    try:
        _stream.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

ROOT = os.path.dirname(os.path.abspath(__file__))
ORIG = {'cloud/atlas_cloud.py': '107c205af112d8733ea5845e90c3b4040db8140ac60f4a6ed47398f12d2f6153', 'core/pc_link.py': 'b0d29925279b44d654e0660b2acc4bcfc095f276a01aa06e445f58b4c23e59a9', 'main.py': 'c59af9972af1806b8e35fba3737c02126f29d45f00d514403f26182114239894', 'tests/test_cloud_brain.py': '02236308d13cc4979a6d045fe2806ce96885a2a6a7894dd99459fea91e832d6e', 'core/worklog.py': None, 'core/workspaces.py': None, 'skills/worklog.py': None, 'tests/test_worklog.py': None}
NEW = {'cloud/atlas_cloud.py': '', 'core/pc_link.py': '', 'main.py': '', 'tests/test_cloud_brain.py': '', 'core/worklog.py': '', 'core/workspaces.py': '', 'skills/worklog.py': '', 'tests/test_worklog.py': ''}
TAG = "backup_pcmem_"


def p(rel):
    return os.path.join(ROOT, *rel.split("/"))


def restore(backup):
    for rel, h in ORIG.items():
        if h is None:
            if os.path.exists(p(rel)):
                os.remove(p(rel))
        else:
            shutil.copy2(os.path.join(backup, *rel.split("/")), p(rel))
    print(f"Вернул прежние файлы из {backup}.")


if "--rollback" in sys.argv:
    cands = sorted(d for d in os.listdir(ROOT) if d.startswith(TAG))
    if not cands:
        sys.exit("Резервной копии нет.")
    restore(p(cands[-1]))
    sys.exit(0)
if os.path.exists(p('core/worklog.py')) and 'def summary' in open(p('core/worklog.py'), encoding="utf-8").read():
    sys.exit("Уже установлено.")

differ = []
for rel, h in ORIG.items():
    if h is None:
        if os.path.exists(p(rel)):
            differ.append(f"{rel} — уже есть такой файл")
        continue
    if not os.path.exists(p(rel)):
        differ.append(f"{rel} — нет файла")
        continue
    got = hashlib.sha256(open(p(rel), "rb").read().replace(b"\r\n", b"\n")).hexdigest()
    if got != h:
        differ.append(rel)
if differ:
    print("  ! отличаются от версии на GitHub: " + ", ".join(differ))
    sys.exit("Эти файлы у тебя изменены — ничего не тронул. Сделай git pull (или пришли мне вывод), потом запусти снова.")

backup = p(time.strftime(TAG + "%Y%m%d_%H%M%S"))
for rel, h in ORIG.items():
    if h is not None:
        os.makedirs(os.path.dirname(os.path.join(backup, *rel.split("/"))), exist_ok=True)
        shutil.copy2(p(rel), os.path.join(backup, *rel.split("/")))
print(f"Резервная копия: {backup}")
for rel, data in NEW.items():
    os.makedirs(os.path.dirname(p(rel)) or ROOT, exist_ok=True)
    with open(p(rel), "wb") as f:
        f.write(base64.b64decode(data))
print("  ✓ память компьютера: «что я делал», «где тот сайт», «открой снова», «на чём я остановился»")
print("  ✓ рабочие места: «сохрани это как Учёба» → «открой рабочее место Учёба»")

env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
suites = [f for f in sorted(os.listdir(p("tests"))) if f.startswith("test_") and f.endswith(".py")]
for suite in suites:
    try:
        r = subprocess.run([sys.executable, p("tests/" + suite)], cwd=ROOT, capture_output=True, text=True,
                           encoding="utf-8", errors="replace", timeout=300, env=env)
        out, code = r.stdout + r.stderr, r.returncode
    except subprocess.TimeoutExpired:
        out, code = "✗ тесты не закончились за 5 минут", 1
    m = re.search(r"Тестов пройдено: (\d+) из (\d+)", out)
    good = code == 0 and m and m.group(1) == m.group(2)
    print(f"  {'✓' if good else '✗'} tests/{suite}: {m.group(0) if m else 'итоговой строки нет'}")
    if not good:
        lines = out.splitlines()
        for i, ln in enumerate(lines):
            if ln.strip().startswith("✗"):
                print("      " + "\n      ".join(x.rstrip() for x in lines[i:i + 7]))
        restore(backup)
        sys.exit("✗ Проверка не прошла — всё возвращено.")
print("\nГотово. Дальше: git add -A, git commit, git push; перезапусти Atlas на компьютере.")
print("Память начнёт копиться с этого запуска: поработай немного и спроси «что я делал сегодня?».")

